def clamp(value, lo, hi):
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value

def is_palindrome(s):
    normalized = ''.join(char for char in s.lower() if char.isalnum())
    return normalized == normalized[::-1]

def average(nums):
    if not nums:
        return None
    return float(sum(nums) / len(nums))

def safe_divide(a, b):
    if b == 0:
        raise ValueError('division by zero')
    return a / b

def flatten(nested):
    result = []
    stack = list(reversed(nested))

    while stack:
        item = stack.pop()
        if isinstance(item, list):
            stack.extend(reversed(item))
        else:
            result.append(item)

    return result

import re
from collections import Counter


def most_common_word(text):
    words = [word.casefold() for word in re.findall(r"[^\\W_]+", text, flags=re.UNICODE)]
    if not words:
        return None

    counts = Counter(words)
    highest_count = max(counts.values())
    return next(word for word in words if counts[word] == highest_count)
